# Source for q/ae-path5.js: Pathology fifth batch (mixed topics, less common conditions).
VD="Valve disease"; CM="Cardiomyopathy"; CW="Coronary & wall motion"; PD="Pericardial disease"
CG="Congenital"; MS="Masses"; AO="Aorta"; PH="Pulmonary hypertension"; TD="Transplant & devices"
Q=[
# --- Valve disease ---
(VD,"Mitral annular disjunction (MAD) is:","A separation between the LA wall–mitral junction and the top of the LV wall, seen in systole",["A cleft in the anterior leaflet","Mitral stenosis","A ruptured chord"],"It is often seen with mitral prolapse and is linked to ventricular arrhythmias.","C"),
(VD,"A unicuspid aortic valve usually presents with:","Severe aortic stenosis at a young age",["Mild AR in old age","No symptoms ever","Mitral stenosis"],"It has a single commissure and an eccentric opening.","C"),
(VD,"A quadricuspid aortic valve most often leads to:","Aortic regurgitation",["Aortic stenosis in childhood","Mitral stenosis","Coarctation"],"It is rare and seen best in PSAX as an 'X' shape in diastole.","C"),
(VD,"Degenerative mitral stenosis from heavy annular calcification differs from rheumatic MS because it has:","No commissural fusion and narrowing at the base of the leaflets",["Fused commissures with doming","A fish-mouth orifice at the tips","Thin leaflets with normal opening"],"Planimetry and PHT are less reliable in calcific MS.","C"),
(VD,"Ankylosing spondylitis is associated with:","Aortic root disease and aortic regurgitation, plus conduction block",["Mitral stenosis","Pulmonic stenosis","Ebstein anomaly"],"Thickening of the aortic root and the base of the anterior mitral leaflet can form a 'subaortic bump'.","C"),
(VD,"Severe TR caused by a pacemaker lead is usually from:","The lead pinning or tethering a tricuspid leaflet",["Rheumatic disease","Carcinoid","Endocarditis always"],"3D echo helps show how the lead crosses the valve.","F"),
(VD,"A meaningful minority (roughly 1 in 7 to 1 in 8) of older patients with severe AS also have:","Transthyretin cardiac amyloidosis",["Kawasaki disease","Ebstein anomaly","Coarctation"],"Amyloid can contribute to low-flow AS.","C"),
(VD,"Tricuspid valve prolapse is defined as:","Leaflet displacement above the tricuspid annulus into the RA in systole",["Leaflet tethering into the RV","Thick leaflets with stenosis","A missing leaflet"],"It is often seen with mitral prolapse.","F"),
(VD,"Mild pulmonic regurgitation in a healthy adult is:","A common normal finding",["Always pathological","A sign of severe PH","A sign of endocarditis"],"Trivial PR and TR are seen in most normal people.","F"),
(VD,"Mucopolysaccharidoses (such as Hurler syndrome) can cause:","Thickened mitral and aortic valves with regurgitation or stenosis",["Normal valves","Coronary aneurysms only","Pericardial calcification"],"Storage material builds up in the valve tissue.","C"),
(VD,"Rheumatic aortic valve disease usually appears along with:","Rheumatic mitral valve disease",["Normal mitral valve","Bicuspid aortic valve","Coarctation"],"Isolated rheumatic aortic disease without mitral involvement is uncommon.","F"),
# --- Coronary ---
(CW,"Myocardial bridging means:","A segment of a coronary artery (often the LAD) runs inside the heart muscle",["A blocked artery","A coronary fistula","A coronary aneurysm"],"Squeezing in systole can occasionally cause ischemia.","C"),
(CW,"Coronary artery ectasia is:","Diffuse dilation of a coronary artery to over 1.5 times the normal size",["A narrowing","A fistula","A spasm"],"It can cause slow flow and clotting.","C"),
(CW,"A type A dissection that extends into the right coronary artery may cause:","An inferior wall motion abnormality",["An anterior wall motion abnormality","Pericarditis only","A normal echo"],"Always look at the aortic root in a patient with an inferior MI and severe chest pain.","C"),
(CW,"Cocaine can cause a heart attack mainly by:","Coronary spasm and increased oxygen demand, sometimes with clotting",["Lowering heart rate","Dilating coronaries","Thinning the blood"],"Young patients with chest pain should be asked about drug use.","F"),
(CW,"After blunt chest trauma, echo may show myocardial contusion as:","A wall motion abnormality that does not match a coronary territory, often in the RV",["Normal motion always","Mitral stenosis","Coarctation"],"Also look for effusion and valve damage.","C"),
(CW,"An LV wall motion abnormality in the territory of a vessel with prior bypass graft may suggest:","Graft disease or occlusion",["Normal finding","Pericarditis","Aortic stenosis"],"Compare with previous studies.","F"),
(CW,"Microvascular angina (coronary microvascular dysfunction) is suggested when:","Ischemia symptoms occur with normal large coronaries and reduced coronary flow reserve",["Coronaries are blocked","There is a valve problem","Wall motion is always abnormal at rest"],"It is more common in women.","C"),
# --- Cardiomyopathy ---
(CM,"Fulminant myocarditis on echo often shows:","A normal-sized LV with thick walls (edema) and severely reduced function",["A large, thin LV with normal function","Normal function","Pericardial constriction"],"Patients can deteriorate quickly and may need mechanical support.","C"),
(CM,"Reverse (inverted) Takotsubo shows:","Basal and mid akinesis with a hyperkinetic apex",["Apical ballooning","Normal walls","RV only involvement"],"It is more common in younger patients.","C"),
(CM,"Danon disease and PRKAG2 syndrome can mimic HCM. A clue is:","Massive LV hypertrophy with conduction disease such as pre-excitation (WPW)",["Thin walls","Normal ECG always","Aortic dilation"],"Genetic testing helps make the diagnosis.","C"),
(CM,"Increased trabeculation in athletes and pregnant women can mimic LV noncompaction, but differs because:","LV function is normal and it often regresses",["EF is low","Thrombus is always present","It never regresses"],"Look at function and clinical context before diagnosing noncompaction.","C"),
(CM,"In patients with HIV, the heart may show:","Dilated cardiomyopathy, pericardial effusion or pulmonary hypertension",["Only mitral stenosis","Only coarctation","No changes"],"Modern treatment has reduced these problems.","C"),
(CM,"Hypertensive heart disease usually shows:","Concentric LV hypertrophy with an enlarged LA and impaired relaxation",["A thin dilated LV","Normal LA always","Apical ballooning"],"Blood pressure control can lead to some regression.","F"),
(CM,"Dilated cardiomyopathy raises the risk of LV thrombus because of:","Slow flow in a large, poorly contracting LV",["Fast flow","Thick walls","Normal function"],"Look for clots at the apex with contrast if needed.","F"),
(CM,"Peripartum cardiomyopathy differs from simple pregnancy changes because it shows:","An EF under 45% in late pregnancy or the months after delivery",["Normal EF with mild LV enlargement","Only a small effusion","Only increased heart rate"],"Normal pregnancy raises stroke volume and LV size slightly.","C"),
# --- Pericardial ---
(PD,"Pericardial calcification is seen on imaging as:","Very bright pericardium with shadowing, suggesting chronic constriction",["A black echo-free space","A mobile mass","Normal pericardium"],"CT shows calcium best.","F"),
(PD,"Transient constrictive pericarditis is:","Constriction after inflammation that improves with anti-inflammatory treatment",["Permanent constriction needing surgery","Tamponade","A congenital defect"],"Inflammatory markers and MRI help identify it.","C"),
(PD,"Chylopericardium is a pericardial collection of:","Lymph fluid (chyle), often after surgery or trauma to the thoracic duct",["Blood","Pus","Air"],"Fluid analysis shows high triglycerides.","C"),
(PD,"Primary pericardial mesothelioma is:","A rare malignant tumor of the pericardium",["A normal finding","A type of cyst","A benign fat deposit"],"It can cause effusion and constriction.","C"),
(PD,"Purulent pericarditis is:","A bacterial infection of the pericardium needing urgent drainage and antibiotics",["A viral infection that resolves alone","A benign condition","A tumor"],"It is life-threatening.","C"),
(PD,"Pericardial effusion after an acute MI in the first days is most often from:","Pericardial inflammation over the infarct (early post-MI pericarditis)",["Coarctation","Mitral stenosis","Aortic stenosis"],"A large or growing effusion raises concern for free wall rupture.","C"),
# --- Masses ---
(MS,"Cardiac lymphoma often:","Infiltrates the right heart and AV groove, surrounding the coronary arteries",["Is a small stalked mass","Arises from valves only","Is always benign"],"It may respond well to chemotherapy.","C"),
(MS,"A cardiac paraganglioma most often arises in the:","Roof of the left atrium",["RV apex","Mitral valve","Aortic arch"],"It may produce hormones that raise blood pressure.","C"),
(MS,"Blood cysts are:","Small, fluid-filled cysts on valves, usually in infants",["Malignant tumors","Vegetations","Thrombus in adults"],"They are usually harmless and may disappear.","C"),
(MS,"A cardiac hemangioma is:","A benign vascular tumor that enhances strongly with contrast",["A malignant tumor","A thrombus","A calcified mass with no blood flow"],"It can occur in any chamber.","C"),
(MS,"An RV thrombus in a patient with acute PE is:","A high-risk finding that needs urgent treatment",["A normal finding","Not important","Always a tumor"],"Clots in transit can embolize at any time.","F"),
(MS,"A prominent Eustachian valve can be told apart from a thrombus because it:","Is a thin, mobile ridge at the IVC–RA junction",["Is a round mass in the RA appendage","Is fixed to the tricuspid leaflet","Grows rapidly"],"Follow it to its attachment at the IVC.","F"),
(MS,"A mass that is fixed, broad-based and in the LA appendage of a patient in AF is most likely:","Thrombus",["Myxoma","Fibroelastoma","Rhabdomyoma"],"Myxomas usually attach to the atrial septum.","F"),
# --- Aorta ---
(AO,"In aortic dissection, the false lumen is usually:","Larger, with slower flow and possible thrombus or spontaneous contrast",["Smaller with faster systolic flow","The same as the true lumen always","Absent"],"The true lumen expands in systole.","F"),
(AO,"Giant cell arteritis can involve the aorta in patients who are usually:","Over 50 years old",["Under 20","Infants","Pregnant only"],"It may lead to aneurysm of the thoracic aorta.","C"),
(AO,"An aberrant right subclavian artery arises from the:","Descending aortic arch and passes behind the esophagus",["Ascending aorta as normal","Pulmonary artery","Left subclavian artery"],"It can cause trouble swallowing (dysphagia lusoria).","C"),
(AO,"A Kommerell diverticulum is:","A bulge at the origin of an aberrant subclavian artery",["A coronary aneurysm","A pericardial cyst","A sinus of Valsalva aneurysm"],"It may need repair if large.","C"),
(AO,"A double aortic arch causes:","A vascular ring around the trachea and esophagus, causing breathing or swallowing problems",["No symptoms ever","Mitral stenosis","Heart block"],"It is usually found in infants.","C"),
(AO,"Malperfusion in aortic dissection means:","Reduced blood flow to organs or limbs because branch arteries are blocked by the flap",["Normal blood flow","Pericardial effusion","Aortic regurgitation"],"It can affect the gut, kidneys, legs or brain.","F"),
(AO,"Chronic high blood pressure often causes:","Mild dilation of the aortic root and ascending aorta",["Narrowing of the aorta","Coarctation","No changes"],"Strict BP control slows enlargement.","F"),
# --- Pulmonary hypertension ---
(PH,"Patients with systemic sclerosis (scleroderma) should have regular screening for:","Pulmonary arterial hypertension",["Mitral stenosis","Coarctation","Bicuspid aortic valve"],"Echo is used for yearly screening.","F"),
(PH,"Portopulmonary hypertension is PAH linked to:","Liver disease with portal hypertension",["Coronary disease","Aortic stenosis","Coarctation"],"It affects suitability for liver transplant.","C"),
(PH,"Pregnancy in a woman with severe PAH is:","Very high risk for the mother",["Safe in all cases","Low risk","Encouraged"],"Specialist care is needed.","F"),
(PH,"Drug groups used to treat PAH include:","Endothelin receptor antagonists, PDE-5 inhibitors and prostacyclins",["Antibiotics","Beta-blockers only","Statins"],"Treatment aims to dilate the pulmonary arteries.","C"),
(PH,"A pulmonary artery aneurysm may develop in:","Long-standing severe pulmonary hypertension",["Normal adults","Mild MR","Coarctation"],"It can compress the left main coronary artery.","C"),
(PH,"Exercise pulmonary hypertension is suggested by a mean PAP to cardiac output slope during exercise of more than:","3 mmHg/L/min",["30 mmHg/L/min","0.1 mmHg/L/min","100 mmHg/L/min"],"It can explain breathlessness in early disease.","C"),
(PH,"Sickle cell disease is associated with which type of PH?","Group 5 (unclear or multiple mechanisms)",["Group 1 only","Group 2 only","Group 4 only"],"A TR velocity over about 2.5 m/s is linked to higher risk in these patients.","C"),
# --- Congenital ---
(CG,"A PFO with an atrial septal aneurysm in a young stroke patient with no other cause may be treated with:","Percutaneous PFO closure",["Mitral valve replacement","Coronary bypass","Pacemaker"],"Trials showed fewer recurrent strokes after closure in selected patients.","F"),
(CG,"A pulmonary artery sling is when the:","Left pulmonary artery arises from the right PA and passes between the trachea and esophagus",["Aorta loops around the trachea","Pulmonary veins drain to the RA","PDA stays open"],"It can compress the airway.","C"),
(CG,"An LV diverticulum is:","A congenital outpouching of the LV wall that contracts with the heart",["A pseudoaneurysm","A tumor","A thrombus"],"Unlike an aneurysm, its wall contains normal contracting muscle.","C"),
(CG,"Subpulmonic (infundibular) stenosis is a key feature of:","Tetralogy of Fallot",["ASD","PDA","Coarctation"],"The RVOT narrowing is caused by anterior deviation of the outlet septum.","F"),
(CG,"A single ventricle heart is usually palliated with:","A staged approach ending with a Fontan operation",["Valve replacement only","No surgery","A pacemaker only"],"Blood from the body flows directly to the lungs without a pumping ventricle.","F"),
(CG,"In an adult with a repaired coarctation and bicuspid aortic valve, routine imaging should include:","The ascending aorta, the repair site and the aortic valve",["Only the mitral valve","Only the RV","Only the pericardium"],"Both conditions can progress over time.","F"),
# --- Transplant & devices ---
(TD,"A new pericardial effusion after pacemaker insertion may suggest:","Lead perforation through the heart wall",["Normal healing","Endocarditis always","Pulmonary embolism"],"Urgent assessment is needed if the effusion grows or causes tamponade.","F"),
(TD,"Pacemaker syndrome in VVI pacing is caused by:","Loss of AV synchrony, so the atria may contract against closed valves",["Too fast heart rate","Lead infection","Battery failure"],"Symptoms include tiredness and dizziness; cannon a waves may be seen.","C"),
(TD,"After PFO closure, echo follow-up checks for:","Residual shunt, device thrombus, erosion and effusion",["Mitral stenosis","Coarctation","Aortic stenosis"],"A bubble study tests for residual shunt.","F"),
(TD,"A percutaneous pulmonary valve (such as the Melody valve) is used for:","Failing RV-to-PA conduits or pulmonary valves after congenital heart surgery",["Mitral stenosis","Aortic stenosis","Coarctation"],"It can delay repeat open surgery.","C"),
(TD,"A heterotopic ('piggyback') heart transplant means:","The donor heart is added alongside the patient's own heart",["The old heart is removed","Only valves are replaced","Lungs are transplanted"],"Echo shows two hearts, with the donor heart in the right chest.","C"),
(TD,"A patient with CRT who does not improve (a 'non-responder') may benefit from echo to check:","LV lead position effect, dyssynchrony and AV delay settings",["Pericardial calcification","Coarctation","Aortic root size only"],"Optimizing device settings can improve response.","C"),
(TD,"Tricuspid transcatheter edge-to-edge repair (TEER) is used for:","Severe symptomatic TR in patients at high surgical risk",["Mitral stenosis","Aortic stenosis","Pulmonic stenosis"],"TEE guides clip placement.","F"),
]
